Each new node is added at the front of this linked list. What does this code print, and how does the cost of `get(head, k)` grow with k, compared with `lst[k]` on a Python list?

class Node:
    def __init__(self, val, nxt=None):
        self.val, self.next = val, nxt

def get(head, k):
    node, hops = head, 0
    for _ in range(k):
        node = node.next
        hops += 1
    return node.val, hops

head = None
for v in [10, 20, 30, 40]:
    head = Node(v, head)
print(get(head, 0), get(head, 3))

This is a tiny hash table with 4 buckets: it uses `key % 4` as the hash function and keeps a list (chain) of [key, value] pairs in each bucket. What does it print? How many key comparisons does looking up 13 take, and what would happen to lookups if every key had the form 4k + 1?

buckets = [[] for _ in range(4)]

def put(key, val):
    bucket = buckets[key % 4]
    for pair in bucket:
        if pair[0] == key:
            pair[1] = val
            return
    bucket.append([key, val])

for k, v in [(5, "a"), (9, "b"), (13, "c"), (6, "d"), (9, "e")]:
    put(k, v)
print(buckets)
print([len(b) for b in buckets])

What does this code print? What would happen if the `if node in seen: continue` check were removed, and why might this explicit-stack version be preferred over a recursive DFS on a graph containing a path of a million nodes?

graph = {1: [2, 3], 2: [4], 3: [4], 4: [1]}

def dfs(start):
    seen, stack, order = set(), [start], []
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        order.append(node)
        for nb in graph[node]:
            stack.append(nb)
    return order

print(dfs(1))
